\draw[->,black,thick] (0,0)--(4.330,-2.5);
\draw[->,componentBlue,thick] (0,0)--(4.330,0);
\draw[->,componentRed,thick] (4.330,0)--(4.330,-2.5);
\draw[angleOrange] (0.9,0) arc[start angle=0,end angle=-30,radius=0.9];
