\path (0.65,1.1) node[right,black,font=\fontsize{10}{12}\selectfont] {$18\text{ m}$};
\path (1,3.45) node[right,black,font=\fontsize{10}{12}\selectfont] {$45\text{ m/s}$};
\path (0.7,2.7) node[black,font=\fontsize{10}{12}\selectfont] {$\theta$};
\path (3,0) node[below,black,font=\fontsize{10}{12}\selectfont] {$y=0$};
